use vstd::prelude::*;

verus! {

fn multiply(a: int, b: int) -> (result: int)
    ensures
        result == a * b
{
    // We first reduce to the case of a non‐negative multiplier b1.
    let mut a1: int = a;
    let mut b1: int = b;
    if b1 < 0 {
        a1 = -a1;
        b1 = -b1;
    }

    // Now  b1 ≥ 0, and we can accumulate a1 exactly b1 times.
    let mut i: int = 0;
    let mut acc: int = 0;
    while i < b1
        invariant
            0 <= i,
            i <= b1,
            acc == a1 * i
        decreases
            b1 - i
    {
        acc = acc + a1;
        i = i + 1;
    }

    // At this point acc == a1 * b1, and since (a1, b1) was chosen so that
    // a1 * b1 == a * b, we return acc.
    acc
}

} // end of verus!{}

